command:
// ==========================================
// LUNAS WIRKUNG: MEISTERKLINGE (RONDRA)
//
// - Ziel: eigene Klingenwaffe
// - nur eine Meisterklinge gleichzeitig
// - TP + mindestens 1, abgerundet QS/3
// - Schaden gegen Geist und Biestinger ×2
// - numerische Schadenswerte: Addieren (2)
// - creatureBonus: Selbsterstellt (0)
// - Dauer: bis zur nächsten Vollmondnacht
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - öffentliche Gabenkarte über Block 11
// ==========================================

(async function () {

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Meisterklinge", vollerName = "Meisterklinge (Rondra)", ahne = "Rondra";
const endeKey = "meisterklingerondra";
const dauerText = "Bis zur nächsten Vollmondnacht";
const endeText =
    "Die geweihte Klinge verliert ihren übernatürlichen Zustand und wird wieder zu einer ganz normalen Waffe. Rondras Segen ruht.";

const forbiddenWords = ["raufen", "bogen", "axt", "hammer", "speer"];

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const findeWaffen = actor => {
    const gesehen = new Map();

    for (const item of actor?.items || []) {
        const typ = String(item.type || "").toLowerCase();

        if (
            typ !== "meleeweapon" &&
            typ !== "rangeweapon" &&
            typ !== "weapon" &&
            !typ.includes("weapon")
        ) continue;

        const name = String(item.name || "").toLowerCase();
        if (forbiddenWords.some(wort => name.includes(wort))) continue;

        gesehen.set(item.id, item);
    }

    return [...gesehen.values()]
        .sort((a, b) => String(a.name).localeCompare(String(b.name), "de"));
};

const findeMeisterklingenEffekte = actor =>
    (actor?.effects || []).filter(effect =>
        effect.getFlag("dsk", "isMeisterklinge") === true &&
        effect.getFlag("dsk", "casterUuid") === actor.uuid
    );

// +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
        null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Rondrakind!");
if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
}

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

const casterName = DSK_FW.ResolveTokenName(casterActor);

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Meisterklinge Probe", "Meisterklinge"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Rondras Macht konnte die Klinge nicht durchdringen.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "Keine Wirkung",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 5 - WAFFENAUSWAHL +++++++++++++++++++++++++++++++++++++++

const waffen = findeWaffen(casterActor);

if (!waffen.length) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn(
        "Luna sagt 🌙: Keine passende Klingenwaffe im Inventar gefunden!"
    );
}

const tpBonus = Math.max(1, Math.floor(qs / 3));

const wirkungText =
    `Die Macht Rondras durchdringt die gewählte Klinge.` +
    `<br><br>Die TP dieser Waffe werden um <b>+${tpBonus}</b> erhöht <span style="font-size:.85em;">(${qs} QS/3)</span>.` +
    `<br>Schaden gegen <b>Biestinger</b> und <b>Geister</b> wird verdoppelt.` +
    `<br>Es kann nur eine Meisterklinge gleichzeitig bestehen.`;

const optionen = waffen
    .map(item => `<option value="${item.id}">${item.name}</option>`)
    .join("");

const itemId = await foundry.applications.api.DialogV2.wait({
    window: { title: gabenName },
    position: { width: 420 },
    content: `<form>
        ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
        <div class="dskbox2" style="margin-top:10px;">
            <p style="font-size:.95em;line-height:1.35;">${wirkungText}</p>
            <div style="margin-top:10px;">
                <label style="font-weight:bold;font-size:.9em;">Wähle deine Klinge:</label>
                <select name="gegenstandId" style="width:100%;padding:4px;margin-top:4px;">
                    ${optionen}
                </select>
            </div>
            <hr>
            <p style="text-align:center;font-weight:bold;">Wirkungsdauer:<br>${dauerText}</p>
        </div>
    </form>`,
    buttons: [
        {
            action: "anwenden",
            label: "Gabe wirken",
            icon: "fas fa-magic",
            default: true,
            callback: event =>
                String(new FormData(event.target.closest("form")).get("gegenstandId") || "") || null
        },
        {
            action: "abbrechen",
            label: "Abbrechen",
            icon: "fas fa-times",
            callback: () => null
        }
    ],
    rejectClose: false
});

if (!itemId) {
    await raeumeQSAuf(casterActor);
    return;
}

const waffe = casterActor.items.get(itemId);

if (!waffe || !waffen.some(item => item.id === waffe.id)) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die ausgewählte Klinge wurde nicht gefunden!");
}

// +++ 6 - ALTE MEISTERKLINGE ENTFERNEN ++++++++++++++++++++++++

const alteEffekte = findeMeisterklingenEffekte(casterActor);

if (alteEffekte.length) {
    await casterActor.deleteEmbeddedDocuments(
        "ActiveEffect",
        alteEffekte.map(effect => effect.id)
    );
}

// +++ 7 - EFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++++++

const effektName = `${vollerName} - ${waffe.name}`;

const changes = [
    { key: "system.meleeStats.damage", mode: 2, value: tpBonus, priority: 20 },
    { key: "system.rangeStats.damage", mode: 2, value: tpBonus, priority: 20 },

    // V14: textbasierte creatureBonus-Einträge = Selbsterstellt.
    { key: "system.creatureBonus", mode: 0, value: "Geist *2", priority: 20 },
    { key: "system.creatureBonus", mode: 0, value: "Biestinger *2", priority: 20 }
];

const effekt = await DSK_FW.Effekt.Anwenden({
    name: effektName,
    ahne,
    beschreibung:
        wirkungText +
        `<br><br><b>Geweihte Klinge:</b> ${waffe.name}` +
        `<br><b>Wirkungsdauer:</b> ${dauerText}`,
    gabeZiel: "",
    qs,
    ziel: casterActor,
    changes,
    origin: casterActor.uuid,
    showIcon: 1,
    flags: { dsk: {
        isMeisterklinge: true,
        casterUuid: casterActor.uuid,
        qs,
        tpBonus,
        waffenId: waffe.id,
        waffenName: waffe.name,
        wirkungsende: {
            sfName: endeKey,
            basisEffektName: vollerName,
            beschreibungFuerEnde: endeText
        }
    }}
});

if (!effekt) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Meisterklinge konnte nicht angelegt werden!");
}

// +++ 8 - EFFEKT KONTROLLIEREN ++++++++++++++++++++++++++++++++

const endeDaten = effekt.getFlag("dsk", "wirkungsende");

const changesKorrekt =
    (effekt.changes || []).some(change =>
        change.key === "system.meleeStats.damage" &&
        Number(change.mode) === 2 &&
        Number(change.value) === tpBonus
    ) &&
    (effekt.changes || []).some(change =>
        change.key === "system.rangeStats.damage" &&
        Number(change.mode) === 2 &&
        Number(change.value) === tpBonus
    ) &&
    (effekt.changes || []).some(change =>
        change.key === "system.creatureBonus" &&
        Number(change.mode) === 0 &&
        change.value === "Geist *2"
    ) &&
    (effekt.changes || []).some(change =>
        change.key === "system.creatureBonus" &&
        Number(change.mode) === 0 &&
        change.value === "Biestinger *2"
    );

const erfolgreich =
    (effekt.name || effekt.label || "") === effektName &&
    effekt.getFlag("dsk", "isMeisterklinge") === true &&
    effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
    effekt.getFlag("dsk", "waffenId") === waffe.id &&
    Number(effekt.getFlag("dsk", "qs")) === qs &&
    Number(effekt.getFlag("dsk", "tpBonus")) === tpBonus &&
    endeDaten?.sfName === endeKey &&
    endeDaten?.basisEffektName === vollerName &&
    changesKorrekt;

if (!erfolgreich) {
    await effekt.delete().catch(() => {});
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Meisterklinge wurde nicht vollständig angelegt!"
    );
}

// +++ 9 - ÖFFENTLICHE GABENKARTE ++++++++++++++++++++++++++++++

await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName,
    ahne,
    beschreibung: wirkungText,
    wirkender: casterName,
    ziele: [{
        name: waffe.name,
        rolle: "Geweihte Klinge"
    }],
    misserfolge: [],
    dauerText,
    gmBereich: false,
    angewendet: true,
    erfolgreich: true,
    anfragenderUserId: game.user.id
});

// +++ 10 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++++++

await raeumeQSAuf(casterActor);

ui.notifications.info(
    `Luna sagt 🌙: ${waffe.name} wurde zu Rondras Meisterklinge.`
);

}).call(this);
